def histogram(test):
    """Given a string representing a space separated lowercase letters, return a dictionary
    of the letter with the most repetition and containing the corresponding count.
    If several letters have the same occurrence, return all of them.

    Example:
    histogram('a b c') == {'a': 1, 'b': 1, 'c': 1}
    histogram('a b b a') == {'a': 2, 'b': 2}
    histogram('a b c a b') == {'a': 2, 'b': 2}
    histogram('b b b b a') == {'b': 4}
    histogram('') == {}

    """
    if not test:
        return {}
    letters = test.split()
    counts = {}
    for letter in letters:
        counts[letter] = counts.get(letter, 0) + 1
    max_count = max(counts.values())
    return {letter: count for letter, count in counts.items() if count == max_count}

def encrypt(s):
    result = []
    for char in s:
        # Shift each character by 4 positions (2 multiplied by 2)
        shifted = chr((ord(char) - ord('a') + 4) % 26 + ord('a'))
        result.append(shifted)
    return ''.join(result)

def sort_array(array):
    """
    Given an array of non-negative integers, return a copy of the given array after sorting,
    you will sort the given array in ascending order if the sum( first index value, last index value) is odd,
    or sort it in descending order if the sum( first index value, last index value) is even.

    Note:
    * don't change the given array.

    Examples:
    * sort_array([]) => []
    * sort_array([5]) => [5]
    * sort_array([2, 4, 3, 0, 1, 5]) => [0, 1, 2, 3, 4, 5]
    * sort_array([2, 4, 3, 0, 1, 5, 6]) => [6, 5, 4, 3, 2, 1, 0]
    """
    if not array:
        return []

    total = array[0] + array[-1]
    if total % 2 == 1:
        return sorted(array)
    else:
        return sorted(array, reverse=True)

def anti_shuffle(s):
    import re
    # Split the string into words and spaces, preserving spaces as tokens
    tokens = re.findall(r'\S+|\s+', s)
    result = []
    for token in tokens:
        if token.isspace():
            # Keep spaces as is
            result.append(token)
        else:
            # Sort the characters of the word/token by ASCII
            sorted_token = ''.join(sorted(token))
            result.append(sorted_token)
    return ''.join(result)

def reverse_delete(s, c):
    filtered = ''.join(ch for ch in s if ch not in c)
    is_palindrome = filtered == filtered[::-1]
    return (filtered, is_palindrome)
